import sys

small = {1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five', 6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine'}
teens = {10: 'Ten', 11: 'Eleven', 12: 'Twelve', 13: 'Thirteen', 14: 'Fourteen', 15: 'Fifteen', 16: 'Sixteen',
         17: 'Seventeen', 18: 'Eighteen', 19: 'Nineteen'}
tens = {2: 'Twenty', 3: 'Thirty', 4: 'Forty', 5: 'Fifty', 6: 'Sixty', 7: 'Seventy', 8: 'Eighty', 9: 'Ninety'}
names = ['Billion', 'Million', 'Thousand', '']

s = sys.stdin.read().split()[0]
if int(s) == 0:
    print('Zero')
else:
    s = s.zfill(12)
    out = []
    for g in range(4):
        chunk = s[3 * g:3 * g + 3]
        h, t, o = int(chunk[0]), int(chunk[1]), int(chunk[2])
        if h + t + o == 0:
            continue
        if h:
            out += [small[h], 'Hundred']
        if t == 1:
            out.append(teens[10 + o])
        else:
            if t:
                out.append(tens[t])
            if o:
                out.append(small[o])
        if names[g]:
            out.append(names[g])
    print(' '.join(out))

